				config,
				req.Name,
				nodeName,
				topologyFileDir,
				topologyLabDir,
				configMaps,
				&definitionChanged,
			); err != nil {
				return nil, nil, "", err
			}

			if err := stageBindFiles(
				config,
				req.Name,
				nodeName,
				topologyFileDir,
				topologyLabDir,
				configMaps,
			); err != nil {
				return nil, nil, "", err
			}

			if err := stageAdditionalNodeFiles(
				config,
				req.Name,
				nodeName,
				topologyFileDir,
				topologyLabDir,
				configMaps,
			); err != nil {
				return nil, nil, "", err
			}
		}
	}

	// Sanitizing after the local files are staged keeps the file lookups on the paths the node
	// names in the topology file spell out, while everything sent to Kubernetes uses the renamed
	// nodes.
	renames, definitionsChanged, err := sanitizeNodeNames(config, nodeNames)
	if err != nil {
		return nil, nil, "", err
	}
	if definitionsChanged {
		definitionChanged = true
	}

	topologyDefinition := req.TopologyDefinition
	if definitionChanged {
		updatedDefinition, err := renderClabernetesTopologyDefinition(config, renames)
		if err != nil {
			return nil, nil, "", fmt.Errorf(
				"failed to render updated clabernetes topology definition: %w",
				err,
			)
		}
		topologyDefinition = updatedDefinition
	}

	stagedConfigMaps := collectStagedConfigMaps(configMaps)
	renameStagedConfigMapNodes(stagedConfigMaps, renames)

	return topologyDefinition, stagedConfigMaps, naming, nil
}

func renderClabernetesTopologyDefinition(
	config *clabRuntimeConfig,
	renames map[string]string,
) ([]byte, error) {
	if config == nil {
		return nil, fmt.Errorf("topology config is nil")
	}

	rendered := &clabernetesRenderConfig{
		Name:     config.Name,
		Prefix:   config.Prefix,
		Mgmt:     config.Mgmt,
		Settings: config.Settings,
	}

	if config.Topology != nil {
		links, err := clabernetesBriefLinks(
			config.Topology.Links,
			defaultMgmtNetwork(config.Mgmt),
		)
		if err != nil {
			return nil, err
		}
		renameBriefLinkEndpoints(links, renames)

		rendered.Topology = &clabernetesRenderTopology{
			Defaults: config.Topology.Defaults,
			Kinds:    config.Topology.Kinds,
			Nodes:    config.Topology.Nodes,
			Groups:   config.Topology.Groups,
			Links:    links,
		}
	}

	return yaml.Marshal(rendered)
}

func clabernetesBriefLinks(
	links []*clablinks.LinkDefinition,
	mgmtNetwork string,
) ([]*clablinks.LinkBriefRaw, error) {
	if len(links) == 0 {
		return nil, nil
	}

	briefLinks := make([]*clablinks.LinkBriefRaw, 0, len(links))
	for _, link := range links {
		if link == nil || link.Link == nil {
			continue
		}

		brief, err := clabernetesBriefLink(link, mgmtNetwork)
		if err != nil {
			return nil, err
		}
		briefLinks = append(briefLinks, brief)
	}

	return briefLinks, nil
}

func clabernetesBriefLink(
	link *clablinks.LinkDefinition,
	mgmtNetwork string,
) (*clablinks.LinkBriefRaw, error) {
	switch raw := link.Link.(type) {
	case *clablinks.LinkBriefRaw:
		return raw, nil
	case *clablinks.LinkVEthRaw:
		return raw.ToLinkBriefRaw(), nil
	case *clablinks.LinkHostRaw:
		return raw.ToLinkBriefRaw(), nil
	case *clablinks.LinkMgmtNetRaw:
		// the brief form has no network field, it always attaches to the default
		// management network
		if raw.Network != "" && raw.Network != mgmtNetwork {
			return nil, fmt.Errorf(
				"clabernetes runtime supports mgmt-net links to the default management "+
					"network %q only, not to %q",
				mgmtNetwork,
				raw.Network,
			)
		}
		return raw.ToLinkBriefRaw(), nil
	case *clablinks.LinkMacVlanRaw:
		return raw.ToLinkBriefRaw(), nil
	default:
		return nil, fmt.Errorf(
			"failed to render clabernetes-compatible brief link for %s link",
			link.Link.GetType(),
		)
	}
}

// defaultMgmtNetwork returns the name of the management network of the topology,
// falling back to the name containerlab uses when the topology does not set one.
func defaultMgmtNetwork(mgmt *clabtypes.MgmtNet) string {
	if mgmt == nil || mgmt.Network == "" {
		return clabconstants.DefaultMgmtNetworkName
	}
	return mgmt.Network
}

func clabernetesNamingMode(config *clabRuntimeConfig) string {
	if config == nil || config.Prefix == nil || *config.Prefix != "" {
		return ""
	}

	return clabernetesNamingNonPrefixed
}

func stageStartupConfig(
	ctx context.Context,
	config *clabRuntimeConfig,
	topologyName,
	nodeName,
	topologyFileDir,
	topologyLabDir string,
	configMaps map[string]*stagedConfigMap,
	definitionChanged *bool,
) error {
	startupConfig := config.Topology.GetNodeStartupConfig(nodeName)
	if startupConfig == "" {
		return nil
	}

	if strings.Contains(startupConfig, "\n") {
		nodeDefinition := config.Topology.Nodes[nodeName]
		if nodeDefinition == nil {
			nodeDefinition = &clabtypes.NodeDefinition{}
			config.Topology.Nodes[nodeName] = nodeDefinition
		}
		nodeDefinition.StartupConfig = inlineStartupConfigMountPath
		*definitionChanged = true

		return stageConfigMapFile(
			configMaps,
			topologyName,
			"inline-startup-config/"+nodeName,
			nodeName,
			inlineStartupConfigMountPath,
			fileModeRead,
			[]byte(startupConfig),
		)
	}

	resolvedStartupConfig, files, err := resolveNodeFileReference(
		ctx, startupConfig, "startup-config", nodeName, topologyFileDir, topologyLabDir,
	)
	if err != nil {
		return fmt.Errorf("failed staging startup-config for node %q: %w", nodeName, err)
	}

	if resolvedStartupConfig != startupConfig {
		nodeDefinition := config.Topology.Nodes[nodeName]
		if nodeDefinition == nil {
			nodeDefinition = &clabtypes.NodeDefinition{}
			config.Topology.Nodes[nodeName] = nodeDefinition
		}
		nodeDefinition.StartupConfig = resolvedStartupConfig
		*definitionChanged = true
	}

	for _, file := range files {
		if err := stageLocalFile(configMaps, topologyName, nodeName, file); err != nil {
			return err
		}
	}

	return nil
}

func stageLicenseFile(
	ctx context.Context,
	config *clabRuntimeConfig,
	topologyName,
	nodeName,
	topologyFileDir,
	topologyLabDir string,
	configMaps map[string]*stagedConfigMap,
	definitionChanged *bool,
) error {
	license := config.Topology.GetNodeLicense(nodeName)
	if license == "" {
		return nil
	}

	resolvedLicense, files, err := resolveNodeFileReference(
		ctx, license, "license", nodeName, topologyFileDir, topologyLabDir,
	)
	if err != nil {
		return fmt.Errorf("failed staging license for node %q: %w", nodeName, err)
	}
	if resolvedLicense != license {
		nodeDefinition := config.Topology.Nodes[nodeName]
		if nodeDefinition == nil {
			nodeDefinition = &clabtypes.NodeDefinition{}
			config.Topology.Nodes[nodeName] = nodeDefinition
		}
		nodeDefinition.License = resolvedLicense
		*definitionChanged = true
	}
	for _, file := range files {
		if err := stageLocalFile(configMaps, topologyName, nodeName, file); err != nil {
			return err
		}
	}

	return nil
}

// resolveNodeFileReference uses the shared downloader for every supported URL scheme and
// preserves the filename (including .partial) that node implementations use to select formats.
func resolveNodeFileReference(
	ctx context.Context,
	sourcePath, field, nodeName, topologyFileDir, topologyLabDir string,
) (string, []stagedLocalFile, error) {
	sourcePath = filepath.ToSlash(replaceClabPathVariables(sourcePath, nodeName, topologyLabDir))
	if strings.Contains(sourcePath, "\n") {
		mountPath := filepath.Join("/clabernetes", nodeName, field, "embedded.lic")
		return mountPath, []stagedLocalFile{{
			filePath: mountPath, mode: fileModeRead, content: []byte(sourcePath),
		}}, nil
	}
	if !clabutils.IsDownloadableURL(sourcePath) {
		files, err := resolveLocalFiles(sourcePath, nodeName, topologyFileDir, topologyLabDir)
		return sourcePath, files, err
	}

	file, err := os.CreateTemp("", "clab-c9s-download-*")
	if err != nil {
		return "", nil, err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	if err := clabutils.CopyFileContents(ctx, sourcePath, file); err != nil {
		return "", nil, err
	}
	info, err := file.Stat()
	if err != nil {
		return "", nil, err
	}
	mountPath := filepath.Join("/clabernetes", nodeName, field,
		filepath.Base(clabutils.FilenameForURL(ctx, sourcePath)))
	staged, err := loadStagedLocalFile(mountPath, file.Name(), info)
	if err != nil {
		return "", nil, err
	}

	return mountPath, []stagedLocalFile{staged}, nil
}

func stageBindFiles(
	config *clabRuntimeConfig,
	topologyName,
	nodeName,
	topologyFileDir,
	topologyLabDir string,
	configMaps map[string]*stagedConfigMap,
) error {
	binds, err := config.Topology.GetNodeBinds(nodeName)
	if err != nil {
		return fmt.Errorf("failed parsing bind mounts for node %q: %w", nodeName, err)
	}
	if len(binds) == 0 {
		return nil
	}

	for _, bind := range binds {
		parsedBind, err := clabtypes.NewBindFromString(bind)
		if err != nil {
			return fmt.Errorf("failed parsing bind %q for node %q: %w", bind, nodeName, err)
		}
		if parsedBind.Src() == "" {
			continue
		}

		if err := stageSourcePathIntoConfigMaps(
			configMaps,
			topologyName,
			parsedBind.Src(),
			nodeName,
			topologyFileDir,
			topologyLabDir,
		); err != nil {
			return err
		}
	}

	return nil
}

// stageAdditionalNodeFiles covers path-bearing fields that containerlab normally resolves on
// the machine running the CLI. A device pod cannot see those paths unless the adapter copies
// them into the node's ConfigMap-backed file projection first.
func stageAdditionalNodeFiles(
	config *clabRuntimeConfig,
	topologyName,
	nodeName,
	topologyFileDir,
	topologyLabDir string,
	configMaps map[string]*stagedConfigMap,
) error {
	pathsByField := map[string][]string{
		"env-files": config.Topology.GetNodeEnvFiles(nodeName),
	}

	// kind-specific config key whose values are paths that a device pod cannot
	// see unless they are staged into the node's ConfigMaps first.
	pathFields := map[string]bool{
		"copy-to-flash": true,
	}

	for _, entry := range config.Topology.GetNodeKindSpecificConfig(nodeName) {
		if !pathFields[entry.Key] {
			continue
		}

		paths, ok := entry.Value.([]any)
		if !ok {
			continue
		}

		pathsByField[entry.Key] = make([]string, 0, len(paths))
		for _, p := range paths {
			if s, ok := p.(string); ok {
				pathsByField[entry.Key] = append(pathsByField[entry.Key], s)
			}
		}
	}

	fieldNames := make([]string, 0, len(pathsByField))
	for fieldName := range pathsByField {
		fieldNames = append(fieldNames, fieldName)
	}
	sort.Strings(fieldNames)

	for _, fieldName := range fieldNames {
		for _, sourcePath := range pathsByField[fieldName] {
			if strings.TrimSpace(sourcePath) == "" {
				continue
			}

			if err := stageSourcePathIntoConfigMaps(
				configMaps,
				topologyName,
				sourcePath,
				nodeName,
				topologyFileDir,
				topologyLabDir,
			); err != nil {
				return fmt.Errorf(
					"failed staging %s path %q for node %q: %w",
					fieldName,
					sourcePath,
					nodeName,
					err,
				)
			}
		}
	}

	return nil
}

func stageSourcePathIntoConfigMaps(
	configMaps map[string]*stagedConfigMap,
	topologyName,
	sourcePath,
	nodeName,
	topologyFileDir,
	topologyLabDir string,
) error {
	files, err := resolveLocalFiles(sourcePath, nodeName, topologyFileDir, topologyLabDir)
	if err != nil {
		return fmt.Errorf(
			"failed staging source path %q for node %q: %w",
			sourcePath,
			nodeName,
			err,
		)
	}

	for _, file := range files {
		if err := stageLocalFile(configMaps, topologyName, nodeName, file); err != nil {
			return err
		}
	}

	return nil
}

func resolveLocalFiles(
	sourcePath,
	nodeName,
	topologyFileDir,
	topologyLabDir string,
) ([]stagedLocalFile, error) {
	displayPath := replaceClabPathVariables(sourcePath, nodeName, topologyLabDir)
	resolvedPath := clabutils.ResolvePath(displayPath, topologyFileDir)

	fileInfo, err := os.Stat(resolvedPath)
	if err != nil {
		return nil, err
	}

	if !fileInfo.IsDir() {
		file, err := loadStagedLocalFile(displayPath, resolvedPath, fileInfo)
		if err != nil {
			return nil, err
		}

		return []stagedLocalFile{file}, nil
	}

	files := []stagedLocalFile{}
	err = filepath.WalkDir(resolvedPath, func(path string, d os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if d.IsDir() {
			return nil
		}

		fileInfo, err := d.Info()
		if err != nil {
			return err
		}

		relativePath, err := filepath.Rel(resolvedPath, path)
		if err != nil {
			return err
		}

		file, err := loadStagedLocalFile(
			filepath.ToSlash(filepath.Join(displayPath, relativePath)),
			path,
			fileInfo,
		)
		if err != nil {
			return err
		}

		files = append(files, file)

		return nil
	})
	if err != nil {
		return nil, err
	}

	sort.Slice(files, func(i, j int) bool {
		return files[i].filePath < files[j].filePath
	})

	return files, nil
}

func loadStagedLocalFile(
	filePath,
	resolvedPath string,
	fileInfo os.FileInfo,
) (stagedLocalFile, error) {
	content, err := os.ReadFile(resolvedPath) //nolint:gosec
	if err != nil {
		return stagedLocalFile{}, err
	}
	if len(content) > maxConfigMapFileBytes {
		return stagedLocalFile{}, fmt.Errorf(
			"file %q is %d bytes, larger than the supported ConfigMap file limit of %d bytes",
			resolvedPath,
			len(content),
			maxConfigMapFileBytes,
		)
	}

	mode := fileModeRead
	if fileInfo.Mode()&0o111 != 0 {
		mode = fileModeExecute
	}

	return stagedLocalFile{
		filePath: filepath.ToSlash(filePath),
		mode:     mode,
		content:  content,
	}, nil
}

func replaceClabPathVariables(sourcePath, nodeName, topologyLabDir string) string {
	labName := filepath.Base(topologyLabDir)
	nodeDir := ""
	if topologyLabDir != "" && nodeName != "" {
		nodeDir = filepath.Join(topologyLabDir, nodeName)
	}

	replacer := strings.NewReplacer(
		clabDirVar, topologyLabDir,
		clabLabNameVar, labName,
		nodeDirVar, nodeDir,
		nodeNameVar, nodeName,
	)

	return replacer.Replace(sourcePath)
}

func stageLocalFile(
	configMaps map[string]*stagedConfigMap,
	topologyName,
	nodeName string,
	file stagedLocalFile,
) error {
	return stageConfigMapFile(
		configMaps,
		topologyName,
		file.filePath,
		nodeName,
		file.filePath,
		file.mode,
		file.content,
	)
}

func stageConfigMapFile(
	configMaps map[string]*stagedConfigMap,
	topologyName,
	identity,
	nodeName,
	filePath,
	mode string,
	content []byte,
) error {
	if len(content) > maxConfigMapFileBytes {
		return fmt.Errorf(
			"file %q is %d bytes, larger than the supported ConfigMap file limit of %d bytes",
			filePath,
			len(content),
			maxConfigMapFileBytes,
		)
	}
	identity = filepath.ToSlash(filepath.Clean(identity))
	configMap, ok := configMaps[identity]
	if ok {
		if existing, _ := configMap.content("file"); !bytes.Equal(existing, content) {
			return fmt.Errorf("staged file path %q has conflicting content", filePath)
		}
	} else {
		configMap = &stagedConfigMap{
			name:       stagedFileConfigMapName(topologyName, identity),
			data:       map[string]string{},
			binaryData: map[string][]byte{},
		}
		if isTextContent(content) {
			configMap.data["file"] = string(content)
		} else {
			configMap.binaryData["file"] = content
		}
		configMaps[identity] = configMap
	}

	for _, mount := range configMap.mounts {
		if mount.nodeName == nodeName && mount.filePath == filePath {
			return nil
		}
	}

	configMap.mounts = append(configMap.mounts, stagedConfigMapMount{
		nodeName:      nodeName,
		filePath:      filePath,
		configMapName: configMap.name,
		configMapPath: "file",
		mode:          mode,
	})

	return nil
}

func stagedFileConfigMapName(topologyName, filePath string) string {
	digest := sha256.Sum256([]byte(filepath.ToSlash(filepath.Clean(filePath))))

	return safeKubernetesName(topologyName, "file", hex.EncodeToString(digest[:])[:16])
}

func collectStagedConfigMaps(configMapGroups ...map[string]*stagedConfigMap) []stagedConfigMap {
	configMaps := []stagedConfigMap{}

	for _, configMapGroup := range configMapGroups {
		nodeNames := make([]string, 0, len(configMapGroup))
		for nodeName := range configMapGroup {
			nodeNames = append(nodeNames, nodeName)
		}
		sort.Strings(nodeNames)

		for _, nodeName := range nodeNames {
			configMap := configMapGroup[nodeName]
			sort.Slice(configMap.mounts, func(i, j int) bool {
				return configMap.mounts[i].filePath < configMap.mounts[j].filePath
			})
			configMaps = append(configMaps, *configMap)
		}
	}

	return configMaps
}

func setTopologyFilesFromConfigMaps(
	topology *unstructured.Unstructured,
	configMaps []stagedConfigMap,
) error {
	if len(configMaps) == 0 {
		return nil
	}

	filesFromConfigMap := map[string]any{}
	for _, configMap := range configMaps {
		for _, mount := range configMap.mounts {
			nodeFiles, _ := filesFromConfigMap[mount.nodeName].([]any)
			nodeFiles = append(nodeFiles, map[string]any{
				"filePath":      mount.filePath,
				"configMapName": mount.configMapName,
				"configMapPath": mount.configMapPath,
				"mode":          mount.mode,
			})
			filesFromConfigMap[mount.nodeName] = nodeFiles
		}
	}

	deployment, found, err := unstructured.NestedMap(topology.Object, "spec", "deployment")
	if err != nil {
		return err
	}
	if !found {
		deployment = map[string]any{}
	}

	deployment["filesFromConfigMap"] = filesFromConfigMap

	return unstructured.SetNestedMap(topology.Object, deployment, "spec", "deployment")
}

func (r *Runtime) applyStagedConfigMaps(
	ctx context.Context,
	namespace string,
	topologyName string,
	configMaps []stagedConfigMap,
	maxWorkers uint,
) error {
	if len(configMaps) == 0 {
		return nil
	}

	workers, clientBurst := r.kubernetesWorkers(maxWorkers)
	warnWorkersExceedBurst("ConfigMap", maxWorkers, clientBurst, len(configMaps))

	return runWithWorkers(configMaps, workers, func(staged stagedConfigMap) error {
		return r.applyStagedConfigMap(ctx, namespace, topologyName, staged)
	})
}

func (r *Runtime) applyStagedConfigMap(
	ctx context.Context,
	namespace string,
	topologyName string,
	staged stagedConfigMap,
) error {
	configMap := stagedConfigMapObject(namespace, topologyName, staged, nil)

	_, err := r.kubeClient.CoreV1().ConfigMaps(namespace).
		Create(ctx, configMap, metav1.CreateOptions{})
	if apierrors.IsAlreadyExists(err) {
		existing, getErr := r.kubeClient.CoreV1().ConfigMaps(namespace).
			Get(ctx, staged.name, metav1.GetOptions{})
		if getErr != nil {
			return fmt.Errorf("failed to get existing staged ConfigMap %s/%s: %w",
				namespace,
				staged.name,
				getErr,
			)
		}

		updated := existing.DeepCopy()
		updated.Labels = mergeDesiredMetadata(existing.Labels, configMap.Labels)
		updated.Data = configMap.Data
		updated.BinaryData = configMap.BinaryData
		err = nil
		if !stagedConfigMapsConform(existing, updated) {
			_, err = r.kubeClient.CoreV1().ConfigMaps(namespace).
				Update(ctx, updated, metav1.UpdateOptions{})
		}
	}
	if err != nil {
		return fmt.Errorf("failed to apply staged ConfigMap %s/%s: %w",
			namespace,
			staged.name,
			err,
		)
	}

	return nil
}

func stagedConfigMapsConform(existing, desired *corev1.ConfigMap) bool {
	return apiequality.Semantic.DeepEqual(existing.Labels, desired.Labels) &&
		apiequality.Semantic.DeepEqual(existing.Data, desired.Data) &&
		apiequality.Semantic.DeepEqual(existing.BinaryData, desired.BinaryData)
}

func stagedConfigMapObject(
	namespace string,
	topologyName string,
	staged stagedConfigMap,
	ownerReferences []metav1.OwnerReference,
) *corev1.ConfigMap {
	// Empty maps are left nil so neither field is serialized when it carries nothing.
	var data map[string]string
	if len(staged.data) != 0 {
		data = staged.data
	}
	var binaryData map[string][]byte
	if len(staged.binaryData) != 0 {
		binaryData = staged.binaryData
	}

	return &corev1.ConfigMap{
		TypeMeta: metav1.TypeMeta{APIVersion: "v1", Kind: "ConfigMap"},
		ObjectMeta: metav1.ObjectMeta{
			Name:            staged.name,
			Namespace:       namespace,
			OwnerReferences: ownerReferences,
			Labels: map[string]string{
				labelApp:           clabernetesAppValue,
				labelTopologyOwner: topologyName,
			},
		},
		Data:       data,
		BinaryData: binaryData,
	}
}

func (r *Runtime) setStagedConfigMapNodeOwnerReferences(
	ctx context.Context,
	namespace string,
	configMaps []stagedConfigMap,
	nodes map[string]*unstructured.Unstructured,
	maxWorkers uint,
) error {
	if len(configMaps) == 0 {
		return nil
	}

	workers, _ := r.kubernetesWorkers(maxWorkers)

	return runWithWorkers(configMaps, workers, func(staged stagedConfigMap) error {
		nodeNames := make(map[string]struct{}, len(staged.mounts))
		for _, mount := range staged.mounts {
			nodeNames[mount.nodeName] = struct{}{}
		}
		sortedNodeNames := make([]string, 0, len(nodeNames))
		for nodeName := range nodeNames {
			sortedNodeNames = append(sortedNodeNames, nodeName)
		}
		sort.Strings(sortedNodeNames)

		ownerReferences := make([]metav1.OwnerReference, 0, len(sortedNodeNames))
		topologyName := ""
		for _, nodeName := range sortedNodeNames {
			node := nodes[nodeName]
			if node == nil {
				return fmt.Errorf("failed to find c9s node %s/%s for staged ConfigMap ownership",
					namespace, nodeName)
			}
			topologyName = node.GetLabels()[labelTopologyOwner]
			ownerReferences = append(ownerReferences, metav1.OwnerReference{
				APIVersion: c9sAPIVersion,
				Kind:       "Node",
				Name:       node.GetName(),
				UID:        node.GetUID(),
			})
		}

		configMap, err := r.kubeClient.CoreV1().ConfigMaps(namespace).
			Get(ctx, staged.name, metav1.GetOptions{})
		if apierrors.IsNotFound(err) {
			configMap = stagedConfigMapObject(
				namespace,
				topologyName,
				staged,
				ownerReferences,
			)
			if _, err = r.kubeClient.CoreV1().ConfigMaps(namespace).
				Create(ctx, configMap, metav1.CreateOptions{}); err != nil {
				return fmt.Errorf(
					"failed to recreate staged ConfigMap %s/%s with owner references: %w",
					namespace,
					staged.name,
					err,
				)
			}

			return nil
		}
		if err != nil {
			return fmt.Errorf("failed to get staged ConfigMap %s/%s for owner update: %w",
				namespace,
				staged.name,
				err,
			)
		}

		if apiequality.Semantic.DeepEqual(configMap.OwnerReferences, ownerReferences) {
			return nil
		}
		configMap.OwnerReferences = ownerReferences

		if _, err = r.kubeClient.CoreV1().ConfigMaps(namespace).
			Update(ctx, configMap, metav1.UpdateOptions{}); err != nil {
			return fmt.Errorf("failed to update staged ConfigMap %s/%s owner references: %w",
				namespace,
				staged.name,
				err,
			)
		}

		return nil
	})
}

func (r *Runtime) deleteStagedConfigMaps(
	ctx context.Context,
	namespace string,
	configMaps []stagedConfigMap,
) {
	for _, staged := range configMaps {
		err := r.kubeClient.CoreV1().ConfigMaps(namespace).
			Delete(ctx, staged.name, metav1.DeleteOptions{})
		if err != nil && !apierrors.IsNotFound(err) {
			log.Debug("failed to delete staged C9s ConfigMap",
				"namespace", namespace,
				"name", staged.name,
				"error", err,
			)
		}
	}
}

func (r *Runtime) deleteStaleConfigMaps(
	ctx context.Context,
	namespace,
	topologyName string,
	desired []stagedConfigMap,
) error {
	desiredNames := make(map[string]struct{}, len(desired))
	for _, staged := range desired {
		desiredNames[staged.name] = struct{}{}
	}

	configMaps, err := r.kubeClient.CoreV1().ConfigMaps(namespace).List(
		ctx,
		metav1.ListOptions{LabelSelector: labelTopologyOwner + "=" + topologyName},
	)
	if err != nil {
		return fmt.Errorf("failed to list staged ConfigMaps for c9s lab %s/%s: %w",
			namespace, topologyName, err)
	}

	for idx := range configMaps.Items {
		name := configMaps.Items[idx].Name
		if _, keep := desiredNames[name]; keep {
			continue
		}
		if err := r.kubeClient.CoreV1().ConfigMaps(namespace).
			Delete(ctx, name, metav1.DeleteOptions{}); err != nil && !apierrors.IsNotFound(err) {
			return fmt.Errorf("failed to delete stale staged ConfigMap %s/%s: %w",
				namespace, name, err)
		}
	}

	return nil
}

func safeKubernetesName(parts ...string) string {
	name := strings.Join(parts, "-")
	if len(name) > kubernetesNameMaxLen {
		digest := sha256.Sum256([]byte(name))
		name = name[0:kubernetesNameMaxLen-8] + "-" + hex.EncodeToString(digest[:])[0:7]
	}

	name = strings.ToLower(name)
	name = invalidDNSLabelChars.ReplaceAllString(name, "-")
	name = startsWithNonAlpha.ReplaceAllString(name, "z")
	name = endsWithNonAlpha.ReplaceAllString(name, "z")

	return name
}

