// credentialsPresent reports whether a credentials block supplies a username/password pair. The
// identity-file is resolved on its own precedence chain (resolveTopologyIdentityFile) and is
// intentionally excluded here so it does not influence the username/password winning level used by
// inventory generation.
func credentialsPresent(c NodeCredentials) bool {
	return c.Username != "" || c.Password != ""
}

// resolveTopologyCredentials returns username and password from the most specific topology level
// where either field is set (node, then group, then kind, then defaults). Values are not merged
// across levels.
func (t *Topology) resolveTopologyCredentials(
	nodeName string,
) (username, password string, src CredentialTopologySource) {
	nodeDefinition, ok := t.Nodes[nodeName]
	if !ok {
		return "", "", CredentialTopologyUnset
	}

	if nodeDefinition != nil && credentialsPresent(nodeDefinition.Credentials) {
		c := nodeDefinition.Credentials
		return c.Username, c.Password, CredentialTopologyNode
	}

	group := t.GetGroup(t.GetNodeGroup(nodeName))
	if group != nil && credentialsPresent(group.Credentials) {
		c := group.Credentials
		return c.Username, c.Password, CredentialTopologyGroup
	}

	kind := t.GetKind(t.GetNodeKind(nodeName))
	if kind != nil && credentialsPresent(kind.Credentials) {
		c := kind.Credentials
		return c.Username, c.Password, CredentialTopologyKind
	}

	defaults := t.GetDefaults()
	if defaults != nil && credentialsPresent(defaults.Credentials) {
		c := defaults.Credentials
		return c.Username, c.Password, CredentialTopologyDefaults
	}

	return "", "", CredentialTopologyUnset
}

// resolveTopologyIdentityFile returns the SSH identity-file path from the most specific topology
// level where it is set (node, then group, then kind, then defaults). It is resolved independently
// of username/password so a node may set only identity-file and still have it apply, without
// affecting the username/password winning level (see resolveTopologyCredentials).
func (t *Topology) resolveTopologyIdentityFile(nodeName string) string {
	nodeDefinition, ok := t.Nodes[nodeName]
	if !ok {
		return ""
	}

	if nodeDefinition != nil && nodeDefinition.Credentials.IdentityFile != "" {
		return nodeDefinition.Credentials.IdentityFile
	}

	if group := t.GetGroup(t.GetNodeGroup(nodeName)); group != nil &&
		group.Credentials.IdentityFile != "" {
		return group.Credentials.IdentityFile
	}

	if kind := t.GetKind(t.GetNodeKind(nodeName)); kind != nil &&
		kind.Credentials.IdentityFile != "" {
		return kind.Credentials.IdentityFile
	}

	if defaults := t.GetDefaults(); defaults != nil && defaults.Credentials.IdentityFile != "" {
		return defaults.Credentials.IdentityFile
	}

	return ""
}

// GetNodeUsername returns the username from the topology credentials block at the winning
// precedence level (see resolveTopologyCredentials). Empty if unset at every level.
func (t *Topology) GetNodeUsername(nodeName string) string {
	u, _, _ := t.resolveTopologyCredentials(nodeName)
	return u
}

// GetNodePassword returns the password from the topology credentials block at the winning
// precedence level (see resolveTopologyCredentials). Empty if unset at every level.
func (t *Topology) GetNodePassword(nodeName string) string {
	_, p, _ := t.resolveTopologyCredentials(nodeName)
	return p
}

// GetNodeIdentityFile returns the SSH identity-file path from the topology credentials block at the
// winning precedence level (see resolveTopologyIdentityFile). Empty if unset at every level.
func (t *Topology) GetNodeIdentityFile(nodeName string) string {
	return t.resolveTopologyIdentityFile(nodeName)
}

// CredentialTopologySource identifies which topology level supplied the credentials block
// before registry fallback. Precedence: node, then group, then kind, then defaults.
type CredentialTopologySource int

const (
	// CredentialTopologyUnset means no topology level set credentials (registry may still fill
	// NodeConfig).
	CredentialTopologyUnset CredentialTopologySource = iota
	CredentialTopologyDefaults
	CredentialTopologyKind
	CredentialTopologyGroup
	CredentialTopologyNode
)

// GetNodeCredentialsTopologySource reports which topology level supplied the credentials pair
// (username and/or password) before registry fallback.
func (t *Topology) GetNodeCredentialsTopologySource(nodeName string) CredentialTopologySource {
	_, _, src := t.resolveTopologyCredentials(nodeName)
	return src
}

// GetComponents returns the node's raw components kind-specific config value, or nil when unset.
//
// Deprecated: components are kind-specific config; use GetNodeKindSpecificConfig. Kept for
// clabernetes, which
// transcodes the value into its own component type.
func (t *Topology) GetComponents(nodeName string) any {
	for _, e := range t.GetNodeKindSpecificConfig(nodeName) {
		if e.Key == "components" {
			return e.Value
		}
	}

	return nil
}

// KindSpecificConfigEntry is a raw kind-specific config key of a node with the topology block it
// came from.
type KindSpecificConfigEntry struct {
	Key   string
	Value any
	// From is the block that set the key: nodes.<name>, groups.<name>, kinds.<name> or defaults.
	From string
}

// GetNodeKindSpecificConfig returns the node's raw kind-specific config keys merged with precedence
// node > group > kind > defaults, sorted by key. The first block that sets a key provides its
// whole value. Nodes absent from the topology have no kind-specific config.
func (t *Topology) GetNodeKindSpecificConfig(nodeName string) []KindSpecificConfigEntry {
	nodeDef, ok := t.Nodes[nodeName]
	if !ok {
		return nil
	}

	group := t.GetNodeGroup(nodeName)
	kind := t.GetNodeKind(nodeName)

	blocks := []struct {
		from string
		def  *NodeDefinition
	}{
		{"nodes." + nodeName, nodeDef},
		{"groups." + group, t.GetGroup(group)},
		{"kinds." + kind, t.GetKind(kind)},
		{"defaults", t.GetDefaults()},
	}

	var entries []KindSpecificConfigEntry

	seen := map[string]bool{}

	for _, b := range blocks {
		if b.def == nil {
			continue
		}

		for k, v := range b.def.KindSpecificConfig {
			if seen[k] {
				continue
			}

			seen[k] = true

			entries = append(entries, KindSpecificConfigEntry{Key: k, Value: v, From: b.from})
		}
	}

	slices.SortFunc(
		entries,
		func(a, b KindSpecificConfigEntry) int { return strings.Compare(a.Key, b.Key) },
	)

	return entries

