		err = yaml.Unmarshal(data, &parsedVars)
		if err != nil {
			return nil, fmt.Errorf("variables file '%s': %w", filepath.Base(varsFile), err)
		}
		mergeTemplateVariables(templateVars, parsedVars)
	}

	return templateVars, nil
