func clabernetesBriefLinks(
	links []*clablinks.LinkDefinition,
	mgmtNetwork string,
) ([]*clablinks.LinkBriefRaw, error) {
	if len(links) == 0 {
		return nil, nil
	}

	briefLinks := make([]*clablinks.LinkBriefRaw, 0, len(links))
	for _, link := range links {
		if link == nil || link.Link == nil {
			continue
