	}

	for i := range volumes {
		elems := strings.Split(volumes[i], ":")

		if len(elems) == 1 {
			// anonymous volume target only
			continue
		}

		if len(elems) > 1 {
			// replace special variables in the volume source
			r := c.magicVarReplacer(nodeName)
			new_vol := r.Replace(elems[0])
			elems[0] = new_vol
			volumes[i] = strings.Join(elems, ":")
		}
	}

	return nil
}

